    "my_rpg", ((fullscreen) ? sfFullscreen : 0) | sfClose, NULL);
    sfRenderWindow_setFramerateLimit(game->win.dow, 60);
    sfRenderWindow_setVerticalSyncEnabled(game->win.dow, sfTrue);
}

