void draw_pause_game_loop(game_t *game)
{
    display_beach(game);
    display_spell_particle(game);
    display_rain_particle(game);
    sfRenderWindow_drawSprite(game->win.dow, game->sprite->back_pause, NULL);
    draw_buttons_pause(game);
