        game->press.click = true;
        sfSprite_setScale(game->sprite->music_but,
        (sfVector2f){4.8 * game->win.ratio, 4.8 * game->win.ratio});
        sfSprite_setPosition(game->sprite->music_but,
        (sfVector2f){842 * game->win.ratio, 367 * game->win.ratio});
