        sfSprite_setScale(game->sprite->music_but,
        (sfVector2f){5 * game->win.ratio, 5 * game->win.ratio});
        sfSprite_setPosition(game->sprite->music_but,
        (sfVector2f){840 * game->win.ratio, 365 * game->win.ratio});
    }
